<script>
  // Highlight the currently visible cards on scroll (IntersectionObserver)
  (function () {
    var cards = document.querySelectorAll('.card');
    var io = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting) {
          entry.target.classList.add('in-view');
        } else {
          entry.target.classList.remove('in-view');
        }
      });
    }, { threshold: 0.5 });
    cards.forEach(function (c) { io.observe(c); });

    // Small fade-in animation for cards, purely CSS driven by the class above
    var style = document.createElement('style');
    style.textContent =
      '.card { opacity: 0.35; transition: opacity 0.5s ease; }' +
      '.card.in-view { opacity: 1; }' +
      '@media print { .card { opacity: 1; } }';
    document.head.appendChild(style);

    // Fallback: if IntersectionObserver is unavailable, show everything
    if (!('IntersectionObserver' in window)) {
      cards.forEach(function (c) { c.classList.add('in-view'); });
    }
  })();
</script>

