def _pseudo_moves(board, white_to_move, rights, ep_sq):
    """All pseudo-legal moves as (from, to, promo) tuples; promo is None
    except for promotions."""
    moves = []
    for idx, piece in enumerate(board):
        if piece is None or piece.isupper() != white_to_move:
            continue
        r, f = divmod(idx, 8)  # r == 0 is rank 8
        kind = piece.lower()

        if kind == "p":
            forward = -8 if white_to_move else 8
            start_rank = 6 if white_to_move else 1
            last_rank = 0 if white_to_move else 7
            promos = ("Q", "R", "B", "N") if white_to_move else ("q", "r", "b", "n")

            # Single push, promoting on the last rank
            target = idx + forward
            if board[target] is None:
                if divmod(target, 8)[0] == last_rank:
                    moves.extend((idx, target, p) for p in promos)
                else:
                    moves.append((idx, target, None))

            # Double push
            if r == start_rank:
                t1 = idx + forward
                t2 = t1 + forward
                if board[t1] is None and board[t2] is None:
                    moves.append((idx, t2, None))

            # Captures (with promotion) and en passant
            for df in (-1, 1):
                if 0 <= f + df < 8:
                    target = idx + forward + df
                    if _is_enemy(board[target], white_to_move):
                        if divmod(target, 8)[0] == last_rank:
                            moves.extend((idx, target, p) for p in promos)
                        else:
                            moves.append((idx, target, None))
                    elif target == ep_sq:
                        # En passant capture onto the target square
                        moves.append((idx, target, None))

        elif kind == "n":
            for dr, df in _KNIGHT_OFFS:
                nr, nf = r + dr, f + df
                if 0 <= nr < 8 and 0 <= nf < 8:
                    target = nr * 8 + nf
                    if board[target] is None or _is_enemy(board[target], white_to_move):
                        moves.append((idx, target, None))

        elif kind == "k":
            for dr in (-1, 0, 1):
                for df in (-1, 0, 1):
                    if dr == 0 and df == 0:
                        continue
                    nr, nf = r + dr, f + df
                    if 0 <= nr < 8 and 0 <= nf < 8:
                        target = nr * 8 + nf
                        if board[target] is None or _is_enemy(board[target], white_to_move):
                            moves.append((idx, target, None))

            # Castling (both wings, both colors)
            for right in rights:
                cfg = _CASTLING[right]
                if idx != cfg["king"] or right[0].isupper() != white_to_move:
