def _perft(state, depth):
    if depth == 0:
        return 1
    board, wtm, rights, ep = state
    total = 0
    for frm, to, promo in _pseudo_moves(board, wtm, rights, ep):
        total += _perft(_make_move(state, frm, to, promo), depth - 1)
    return total


