    return [sq(frm) + sq(to) + (promo or "") for frm, to, promo in _pseudo_moves(board, wtm, rights, ep)]


def perft(fen: str, depth: int) -> int:
    if depth < 0:
        raise ValueError("depth must be >= 0")
    board, wtm, rights, ep = _parse_fen(fen)
    return _perft((tuple(board), wtm, rights, ep), depth)

